      <div class="field">
        <span class="field-label">Question</span>
        <textarea class="input" rows="3">Which planet is the largest?</textarea>
      </div>

      <div class="field">
        <span class="field-label">Options</span>
        <span class="field-hint">Mark the correct options, at least one. Empty rows are skipped.</span>
      </div>

