// No network services, client-side persistence, or build step are needed.
document.addEventListener("submit", (event) => {
  const message = event.target.dataset.confirm;
  if (message && !window.confirm(message)) event.preventDefault();
});

document.addEventListener("change", (event) => {
  if (event.target.matches("[data-autosave]")) event.target.form.requestSubmit();
});

const questionForm = document.querySelector("[data-question-form]");
if (questionForm) {
  const rows = questionForm.querySelector("[data-option-rows]");
  const renumber = () => {
    rows.querySelectorAll(".option-row").forEach((row, index) => {
      const prefix = `question[option_rows][${index}]`;
      const text = row.querySelector("[data-option-text]");
      text.name = `${prefix}[text]`;
      text.id = `option-${index}`;
      text.placeholder = `Option ${index + 1}`;
      text.setAttribute("aria-label", `Option ${index + 1}`);
      row.querySelector("[data-option-unchecked]").name = `${prefix}[correct]`;
      const correct = row.querySelector("[data-option-correct]");
      correct.name = `${prefix}[correct]`;
      correct.id = `option-correct-${index}`;
      correct.setAttribute("aria-label", `Option ${index + 1} is correct`);
      const remove = row.querySelector("[data-remove-option]");
      remove.setAttribute("aria-label", `Remove option ${index + 1}`);
      remove.title = `Remove option ${index + 1}`;
    });
  };
  questionForm.querySelector("[data-add-option]").addEventListener("click", () => {
    rows.append(questionForm.querySelector("[data-option-template]").content.cloneNode(true));
    renumber();
    rows.lastElementChild.querySelector("input").focus();
  });
  rows.addEventListener("click", (event) => {
    const button = event.target.closest("[data-remove-option]");
    if (!button) return;
    const row = button.closest(".option-row");
    const nextFocus = row.nextElementSibling || row.previousElementSibling;
    row.remove();
    renumber();
    (nextFocus?.querySelector("input") || questionForm.querySelector("[data-add-option]")).focus();
  });
  renumber();
}

const preview = document.querySelector("[data-preview]");
if (preview) {
  const questions = JSON.parse(preview.querySelector("[data-preview-data]").textContent);
  if (questions.length) {
    // All answer state is local to this page. Reloading starts a fresh preview.
    let index = 0;
    let score = 0;
    let answered = false;
    const questionView = preview.querySelector("[data-preview-question]");
    const resultView = preview.querySelector("[data-preview-result]");
    const progress = preview.querySelector("[data-progress]");
    const heading = preview.querySelector("[data-question-text]");
    const options = preview.querySelector("[data-preview-options]");
    const feedback = preview.querySelector("[data-feedback]");
    const next = preview.querySelector("[data-next-question]");
    const scoreHeading = preview.querySelector("[data-score]");

    const letter = (number) => {
      let result = "";
      do {
        result = String.fromCharCode(65 + number % 26) + result;
        number = Math.floor(number / 26) - 1;
      } while (number >= 0);
      return result;
    };

    const pickOption = (picked) => {
      if (answered) return;
      answered = true;
      const question = questions[index];
      const correct = question.options[picked].correct;
      if (correct) score += 1;
      options.classList.add("is-revealed");
      Array.from(options.children).forEach((button, optionIndex) => {
        button.disabled = true;
        button.classList.toggle("is-picked", optionIndex === picked);
        if (question.options[optionIndex].correct) {
          button.classList.add("is-correct");
          const mark = document.createElement("span");
          mark.className = "play-option__mark";
          mark.textContent = "✓ Correct";
          button.append(mark);
        }
      });
      feedback.textContent = correct ? "Correct!" : "Wrong!";
      feedback.className = `play-status play-status--${correct ? "right" : "wrong"}`;
      feedback.hidden = false;
      next.textContent = index === questions.length - 1 ? "See score" : "Next question";
      next.hidden = false;
      next.focus();
    };

    const showQuestion = (focus = true) => {
      answered = false;
      questionView.hidden = false;
      resultView.hidden = true;
      feedback.hidden = true;
      next.hidden = true;
      progress.textContent = `Question ${index + 1} of ${questions.length}`;
      heading.textContent = questions[index].body;
      options.replaceChildren();
      options.classList.remove("is-revealed");
      questions[index].options.forEach((option, optionIndex) => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "play-option";
        const badge = document.createElement("span");
        badge.className = "play-option__letter";
        badge.textContent = letter(optionIndex);
        badge.setAttribute("aria-hidden", "true");
        const title = document.createElement("span");
        title.className = "play-option__title";
        title.textContent = option.text;
        button.append(badge, title);
        button.addEventListener("click", () => pickOption(optionIndex));
        options.append(button);
      });
      if (focus) heading.focus();
    };

    next.addEventListener("click", () => {
      if (!answered) return;
      if (index < questions.length - 1) {
        index += 1;
        showQuestion();
      } else {
        questionView.hidden = true;
        resultView.hidden = false;
        scoreHeading.textContent = `Score: ${score}/${questions.length}`;
        scoreHeading.focus();
      }
    });
    preview.querySelector("[data-start-over]").addEventListener("click", () => {
      index = 0;
      score = 0;
      showQuestion();
    });
    showQuestion(false);
  }
}
